const colors={Primary:'#168078',Secondary:'#d39a31',Tertiary:'#6654a4',Unclassified:'#80909c'};
const labels={photo:'Phototherapy',cpap:'CPAP respiratory support',power:'Electricity',solar:'Solar backup',water:'Running water',surgery:'Paediatric surgery (mission)',neonatal:'Tertiary neonatal care'};
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let publicCatalog={sources:{},serviceLabels:{}},facilities=[],visible=[],selected=null,selectedLevels=new Set(),markers=new Map();
const map=L.map('map',{zoomControl:false,zoomSnap:0.25}).setView([13.48,-15.35],8);L.control.zoom({position:'topright'}).addTo(map);L.control.scale({imperial:false,position:'bottomright'}).addTo(map);
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',subdomains:'abcd',maxZoom:19}).addTo(map);
const group=L.layerGroup().addTo(map);
function careLevel(f){return f[$('classification').value==='neonatal'?'neonatalLevel':'generalLevel']}
function classificationName(){return $('classification').value==='neonatal'?'Neonatal':'General'}
function classificationChanged(){selectedLevels=new Set();$('search').value='';$('resource').value='';$('status').value='yes';$('status').disabled=true;closeDetail();drawLevels();render();fit();}
$('classification').onchange=classificationChanged;
function provision(f,key){if(key==='public:staff')return f.public?.workforce?.length?'yes':'unknown';if(key.startsWith('public:'))return f.public?.services?.filter(r=>r.key===key.slice(7)).at(-1)?.status||'unknown';return f.resources[key]||'unknown'}
function coverageMatches(f){const v=$('coverage').value;return v==='assessed'?f.assessed:v==='services'?!!f.public?.services?.length:v==='staff'?!!f.public?.workforce?.length:true}
function sourceLink(r){const src=publicCatalog.sources[r.source];return `<a href="${esc(src.url)}" target="_blank" rel="noopener">${esc(src.title)}${r.locator?' · '+esc(r.locator):''} ↗</a>`}
function publicProfile(f){const p=f.public||{services:[],workforce:[],notes:[]};return `<section class="public-profile"><h3>Publicly documented services</h3>${p.services.length?'<p class="record-note">Current availability unverified; dates below.</p>':''}${p.services.length?p.services.map(r=>`<div class="public-record"><div><strong>${esc(publicCatalog.serviceLabels[r.key])}</strong><span class="${r.status}">${r.status==='yes'?'Reported':r.status==='no'?'Not provided':'Limited / uncertain'}</span></div><small>${esc(r.asOf)} · ${sourceLink(r)}</small>${r.note?`<p>${esc(r.note)}</p>`:''}</div>`).join(''):'<p>unavailable</p>'}<h3>Public workforce records</h3>${p.workforce.length?'<p class="record-note">Published headcounts; dates below. Categories may overlap.</p>':''}${p.workforce.length?p.workforce.map(r=>`<div class="public-record"><div><strong>${esc(r.cadre)}</strong><b>${r.operator==='>'?'More than ':''}${esc(r.value)}</b></div><small>${esc(r.asOf)} · ${sourceLink(r)}</small><p>${esc(r.scope)}${r.referenceMinimum!==null&&r.referenceMinimum!==undefined?' Reference minimum in source: '+esc(r.referenceMinimum)+'; not an observed staff count.':''}${r.note?' '+esc(r.note):''}</p></div>`).join(''):'<p>unavailable</p>'}${p.notes.map(n=>`<p class="public-alert">${esc(n.text)} ${sourceLink(n)}</p>`).join('')}</section>`}
function matching(f){return($('classification').value!=='neonatal'||f.assessed)&&(selectedLevels.size===0||selectedLevels.has(careLevel(f)))&&coverageMatches(f)&&(! $('search').value.trim()||`${f.name} ${f.aliases} ${f.region}`.toLowerCase().includes($('search').value.trim().toLowerCase()))&&(!$('resource').value||provision(f,$('resource').value)===$('status').value)}
function render(){visible=facilities.filter(matching);group.clearLayers();markers.clear();$('count').textContent=`${visible.length} facilit${visible.length===1?'y':'ies'}`;$('mapstats').textContent=$('classification').value==='neonatal'?`Neonatal assessment · ${visible.length} of ${facilities.filter(f=>f.assessed).length} facilities shown`:`General care levels · ${visible.length} facilities shown`;
$('results').innerHTML=visible.length?visible.map(f=>`<button class="facility${selected===f.id?' selected':''}" data-id="${esc(f.id)}"><strong>${esc(f.name)}</strong><small><span class="dot" style="background:${colors[careLevel(f)]}"></span>${esc(careLevel(f))} ${classificationName().toLowerCase()} · ${esc(f.region)}${f.assessed?'<span class="assessed">ASSESSED</span>':''}</small></button>`).join(''):'<div class="empty">No facilities match these filters. Try another provision status or reset the filters.</div>';
visible.forEach(f=>{let m=L.circleMarker([f.lat,f.lng],{radius:7,color:'white',weight:1.8,fillColor:colors[careLevel(f)],fillOpacity:.92}).addTo(group).bindTooltip(esc(f.name),{direction:'top'}).on('click',()=>select(f.id));markers.set(f.id,m)});
if(selected&&!visible.some(f=>f.id===selected))closeDetail();else if(selected)highlight();
}
function highlight(){markers.forEach((m,id)=>m.setStyle({radius:7,weight:id===selected?3:1.8,color:id===selected?'#193e42':'white'}))}
function neonatalProfile(f){
  if(!f.assessed)return '<div class="eyebrow">NEONATAL ASSESSMENT</div><p>unavailable</p>';
  return `<div class="eyebrow">NEONATAL ASSESSMENT · NOVEMBER 2025</div>${Object.entries(labels).map(([k,label])=>{const v=f.resources[k]||'unknown';return `<div class="resourceRow"><span>${label}</span><strong class="${v}">${v==='yes'?(k==='photo'?'Some · insufficient':'Available'):'unavailable'}</strong></div>`}).join('')}<details><summary>Assessment notes</summary><p>PATG workshop, 12–13 November 2025. Electricity/water may be intermittent despite “Yes” responses. CPAP: structured table used; conflicting workshop comments remain unresolved.${f.resources.surgery?' Paediatric surgery: November 2025 HF mission activity; ongoing availability unconfirmed.':''}</p></details>`;
}
function select(id){let f=facilities.find(f=>f.id===id);selected=id;map.setView([f.lat,f.lng],Math.max(map.getZoom(),11));$('detail').hidden=false;$('detail').innerHTML=`<button class="close" id="closeDetail" aria-label="Close facility details">×</button><div class="eyebrow">FACILITY PROFILE</div><h2>${esc(f.name)}</h2><span class="badge">General: ${esc(f.generalLevel)}</span> <span class="badge">Neonatal: ${f.assessed?esc(f.neonatalLevel):'unavailable'}</span><p>${esc(f.region)} · ${esc(f.ownership)}<br>${esc(f.type)}</p>${publicProfile(f)}${neonatalProfile(f)}<details class="profile-evidence"><summary>Classification & location sources</summary><p><b>General classification evidence:</b> ${esc(f.generalLevelEvidence)}<br><b>General level:</b> ${esc(f.generalLevelBasis)}${f.assessed?`<br><b>Neonatal level:</b> ${esc(f.neonatalLevelBasis)}`:''}</p><p><b>${f.approx?'Approximate locality position':'Source coordinates'}</b><br>${f.lat.toFixed(5)}, ${f.lng.toFixed(5)}<br>${esc(f.locationSource)}</p><a href="${esc(f.locationUrl)}" target="_blank" rel="noopener">View location source ↗</a><p>Recorded name: ${esc(f.aliases)}</p></details>`;$('closeDetail').onclick=closeDetail;document.querySelectorAll('.facility').forEach(b=>b.classList.toggle('selected',b.dataset.id===id));highlight()}
function closeDetail(){selected=null;$('detail').hidden=true;document.querySelectorAll('.facility').forEach(b=>b.classList.remove('selected'));highlight()}
function fit(){if(visible.length)map.fitBounds(L.latLngBounds(visible.map(f=>[f.lat,f.lng])),{padding:[35,100],maxZoom:13})}
$('results').onclick=e=>{let b=e.target.closest('[data-id]');if(b)select(b.dataset.id)};
['search','coverage','status'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',render));$('resource').onchange=()=>{$('status').disabled=!$('resource').value;render()};
function drawLevels(){const neonatal=$('classification').value==='neonatal';if($('coverage').dataset.context!==$('classification').value){$('coverage').innerHTML=neonatal?`<option value="assessed">All ${facilities.filter(f=>f.assessed).length} neonatal assessment facilities</option>`:'<option value="all">All mapped facilities</option><option value="assessed">November 2025 assessed facilities</option><option value="services">With public service records</option><option value="staff">With public staff counts</option>';$('coverage').disabled=neonatal;$('coverage').dataset.context=$('classification').value;}$('levelLabel').textContent=classificationName()+' level of care';$('legendTitle').textContent=classificationName()+' care';$('levelHint').textContent='Select one or more levels. '+($('classification').value==='neonatal'?'All 14 retained neonatal assessment facilities: 8 primary, 5 secondary and 1 tertiary.':'Uses the intended structure in strategic plan §4.1. Historical type-based assignments are provisional; §2.7 differs on minor centres. See Data & sources.');$('levels').innerHTML=['All',...Object.keys(colors)].map(l=>`<button data-level="${l}" aria-pressed="${l==='All'?selectedLevels.size===0:selectedLevels.has(l)}" class="${(l==='All'?selectedLevels.size===0:selectedLevels.has(l))?'active':''}">${l}</button>`).join('')}
$('levels').onclick=e=>{const clicked=e.target.closest('[data-level]');if(!clicked)return;const chosen=clicked.dataset.level;if(chosen==='All')selectedLevels.clear();else if(selectedLevels.has(chosen))selectedLevels.delete(chosen);else selectedLevels.add(chosen);drawLevels();render();$('levels').querySelector(`[data-level="${chosen}"]`).focus()};
$('reset').onclick=()=>{selectedLevels=new Set();closeDetail();$('search').value='';$('coverage').value=$('classification').value==='neonatal'?'assessed':'all';$('resource').value='';$('status').value='yes';$('status').disabled=true;drawLevels();render();fit()};$('fit').onclick=fit;
$('sourcesButton').onclick=()=>$('sources').showModal();$('closeSources').onclick=()=>$('sources').close();$('sources').onclick=e=>{if(e.target===$('sources')){const r=$('sources').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('sources').close()}};
$('export').onclick=()=>{const headers=['Facility','General care level','Neonatal care level','Facility type','Region','Ownership','Latitude','Longitude','Approximate location','Assessment Nov 2025',...Object.values(labels),'Location source','General level basis','General classification evidence','General classification source','Neonatal level basis','Public service records (dated JSON)','Public staffing records (dated JSON)'];const quote=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';const csv=[headers,...visible.map(f=>[f.name,f.generalLevel,f.neonatalLevel,f.type,f.region,f.ownership,f.lat,f.lng,f.approx,f.assessed,...Object.keys(labels).map(k=>f.resources[k]||'unknown'),f.locationSource,f.generalLevelBasis,f.generalLevelEvidence,f.generalLevelSource,f.neonatalLevelBasis,JSON.stringify(f.public.services.map(r=>({...r,sourceUrl:publicCatalog.sources[r.source].url}))),JSON.stringify(f.public.workforce.map(r=>({...r,sourceUrl:publicCatalog.sources[r.source].url})))])].map(r=>r.map(quote).join(',')).join('\r\n');let u=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='gambia-health-facilities.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
async function init(){try{const r=await fetch('facilities.json');if(!r.ok)throw Error('Facility data failed to load');facilities=await r.json();const catalogResponse=await fetch('public-sources.json');if(!catalogResponse.ok)throw Error('Public source catalog failed to load');publicCatalog=await catalogResponse.json();const publicGroup=document.createElement('optgroup');publicGroup.label='Public service records · dates vary';publicGroup.innerHTML='<option value="public:staff">Published staff counts</option>'+Object.entries(publicCatalog.serviceLabels).map(([k,v])=>`<option value="public:${esc(k)}">${esc(v)}</option>`).join('');$('resource').appendChild(publicGroup);const serviceCount=facilities.filter(f=>f.public.services.length).length,staffCount=facilities.filter(f=>f.public.workforce.length).length;$('publicCoverageNote').textContent=`Public sources reviewed 5 November 2026: ${serviceCount} facilities have service records and ${staffCount} have staffing counts. No comparable public dataset covering all 102 facilities was retrieved. Most quantitative observations are from 2022, not 2026.`;$('publicSourceList').innerHTML=Object.entries(publicCatalog.sources).map(([id,src])=>`<p><a href="${esc(src.url)}" target="_blank" rel="noopener">${esc(src.title)}</a><br>${esc(src.kind)} · Published: ${esc(src.published)} · Observations: ${esc(src.observed)}. Accessed 5 November 2026.</p>`).join('');$('coverageNote').textContent=`${facilities.length} facilities: 101 historical public-sector database records plus Njau from the supplied assessment. One facility has been excluded at the dataset owner’s request; 14 assessment facilities remain. Private, new, renamed, closed and unmapped facilities may be missing. Only 14 have structured neonatal resource assessments. Additional public service and workforce records have partial coverage. In profiles, “unavailable” for missing information means no record is available; it does not establish that a service is absent. Njau is placed at an approximate village location. Neonatal levels and general health-system levels are recorded separately. The neonatal view contains the 14 retained assessment facilities, with eight primary, five secondary and one tertiary neonatal unit. The general-services view contains the wider 102-facility dataset. Neonatal levels follow Dr Hammad Khan’s classifications, including primary designation for the eight previously unclassified assessment facilities. Switch the classification selector to compare the two contexts.`;drawLevels();render();fit();const b=await fetch('gambia-boundary.json');if(b.ok)L.geoJSON(await b.json(),{interactive:false,style:{color:'#408479',weight:1.6,fillColor:'#70ad8b',fillOpacity:.06}}).addTo(map).bringToBack()}catch(e){$('results').textContent='Unable to load facility data. Please reload the page.';console.error(e)}}init();
